import { ref, computed } from 'vue'

export interface ValidationRule {
  required?: boolean
  minLength?: number
  maxLength?: number
  pattern?: RegExp
  message?: string
}

export function useValidation(rules: Record<string, ValidationRule[]>) {
  const errors = ref<Record<string, string>>({})

  function validate(data: Record<string, any>): boolean {
    errors.value = {}
    for (const [field, fieldRules] of Object.entries(rules)) {
      const value = data[field]
      for (const rule of fieldRules) {
        if (rule.required && !value) {
          errors.value[field] = rule.message || (field + ' 不能为空')
          break
        }
        if (rule.minLength && (value || '').length < rule.minLength) {
          errors.value[field] = rule.message || (field + ' 至少 ' + rule.minLength + ' 个字符')
          break
        }
        if (rule.pattern && !rule.pattern.test(value || '')) {
          errors.value[field] = rule.message || (field + ' 格式不正确')
          break
        }
      }
    }
    return Object.keys(errors.value).length === 0
  }

  const isValid = computed(() => Object.keys(errors.value).length === 0)

  return { errors, validate, isValid }
}
